const item = $input.first().json;
const domain = item.domain || $('Split Domains').first().json.domain;
const now = new Date();

let expiryDate = null;
let registrar = 'N/A';
let nameservers = 'N/A';

// Try to extract expiry from various WHOIS response formats
const expiryFields = [
  item.expiry_date, item.expiration_date, item.registry_expiry_date,
  item.expires, item.paid_till, item.domain_expiry
];

for (const field of expiryFields) {
  if (field) {
    expiryDate = new Date(field);
    if (!isNaN(expiryDate.getTime())) break;
    expiryDate = null;
  }
}

if (item.registrar) registrar = item.registrar;
if (item.name_servers) nameservers = Array.isArray(item.name_servers) ? item.name_servers.join(', ') : item.name_servers;

const daysUntilExpiry = expiryDate ? Math.ceil((expiryDate - now) / (1000 * 60 * 60 * 24)) : -1;

let alertLevel = 'OK';
if (daysUntilExpiry <= 7 && daysUntilExpiry >= 0) alertLevel = 'CRITICAL';
else if (daysUntilExpiry <= 30) alertLevel = 'WARNING';
else if (daysUntilExpiry <= 60) alertLevel = 'NOTICE';
else if (daysUntilExpiry < 0) alertLevel = 'UNKNOWN';

return [{
  json: {
    domain,
    expiryDate: expiryDate ? expiryDate.toISOString().split('T')[0] : 'Unknown',
    daysUntilExpiry,
    alertLevel,
    registrar,
    nameservers,
    timestamp: now.toISOString()
  }
}];

